    imageHint: "Puy de Dome volcanic dome",
    descriptionAdvanced: {
      de: "Der Puy de Dôme ist ein markanter Lavadom und der bekannteste Vulkan der Chaîne des Puys im französischen Zentralmassiv. Er liegt etwa 15 Kilometer von der Stadt Clermont-Ferrand entfernt und erreicht eine Höhe von 1465 Metern über dem Meeresspiegel. Der Vulkan entstand vor etwa 11.000 Jahren durch eine gewaltige Eruption und zeichnet sich durch seine abgerundete Form ohne Krater aus. Auf dem Gipfel befinden sich die Ruinen eines gallo-römischen Merkurtempels aus dem 2. Jahrhundert, was die historische Bedeutung dieses Ortes unterstreicht. Heute ist der Puy de Dôme ein bedeutendes Touristenziel und gehört seit 2018 zum UNESCO-Weltnaturerbe als Teil der tektonischen Arena Chaîne des Puys - Limagne-Verwerfung. Besucher können den Gipfel entweder zu Fuß über den alten Pilgerweg \"Sentier des Muletiers\" oder mit der Zahnradbahn \"Panoramique des Dômes\" erreichen. Der Berg bietet einen spektakulären Rundblick auf die umliegenden 80 Vulkankegel und ist zudem ein beliebter Startplatz für Gleitschirmflieger.",
      hu: "A Puy de Dôme egy látványos lávadóm és a Francia-középhegységben található Chaîne des Puys vulkánlánc legismertebb tagja. Clermont-Ferrand városától mindössze 15 kilométerre fekszik, és 1465 méteres magasságával messziről felismerhető a tájban. A vulkán körülbelül 11 000 évvel ezelőtt alakult ki egy heves kitörés során, és sajátossága, hogy nincs klasszikus krátere, hanem egy lekerekített dómot formáz. A csúcson egy 2. századi gall-római Merkúr-templom romjai találhatók, ami jelzi a hely ókori vallási jelentőségét. Napjainkban a Puy de Dôme kiemelt turisztikai célpont, és 2018 óta az UNESCO Világörökség része a Chaîne des Puys tektonikai régió részeként. A látogatók gyalogosan az ősi zarándokúton, a \"Sentier des Muletiers\"-en keresztül, vagy a modern fogaskerekű vasúttal, a \"Panoramique des Dômes\"-szal juthatnak fel a tetőre. A panoráma innen lenyűgöző rálátást nyújt a környező 80 vulkáni kúpra, és a hely népszerű a siklóernyősök körében is.",
      ro: "Puy de Dôme este un dom vulcanic proeminent și cel mai faimos vulcan din lanțul Chaîne des Puys, situat în Masivul Central francez. Aflat la aproximativ 15 kilometri de orașul Clermont-Ferrand, acesta atinge o altitudine de 1465 de metri deasupra nivelului mării. Vulcanul s-a format în urmă cu circa 11.000 de ani printr-o erupție explozivă, caracterizându-se printr-o formă rotunjită, fără crater vizibil. Pe vârf se găsesc ruinele unui templu galo-roman dedicat lui Mercur, datând din secolul al II-lea, fapt ce atestă importanța istorică și spirituală a locului. În prezent, Puy de Dôme este o destinație turistică majoră și face parte din Patrimoniul Mondial UNESCO începând cu anul 2018, ca element central al arenei tectonice Chaîne des Puys. Turiștii pot ajunge la vârf fie pe jos, pe vechiul drum al pelerinilor numit \"Sentier des Muletiers\", fie cu trenul cu cremalieră \"Panoramique des Dômes\". Muntele oferă o vedere panoramică spectaculoasă asupra celorlalți 80 de vulcani din jur și este un loc preferat pentru parapantiști.",
      en: "Puy de Dôme is a prominent lava dome and the most famous volcano in the Chaîne des Puys range within the French Massif Central. Located about 15 kilometers from the city of Clermont-Ferrand, it reaches an elevation of 1,465 meters above sea level. The volcano was formed approximately 11,000 years ago during a series of explosive eruptions, giving it its characteristic rounded shape without a visible crater. The summit is home to the remains of a Gallo-Roman temple dedicated to Mercury, dating back to the 2nd century, which highlights the site's ancient historical importance. Today, Puy de Dôme is a major tourist attraction and has been part of the UNESCO World Heritage list since 2018 as part of the Chaîne des Puys tectonic arena. Visitors can reach the summit either on foot via the ancient pilgrim path called \"Sentier des Muletiers\" or by the \"Panoramique des Dômes\" rack railway. The mountain offers spectacular views of the surrounding 80 volcanic cones and is a popular launch site for paragliders.",
      es: "El Puy de Dôme es un prominente domo de lava y el volcán más famoso de la Chaîne des Puys, en el Macizo Central francés. Se encuentra a unos 15 kilómetros de la ciudad de Clermont-Ferrand y alcanza una altitud de 1465 metros sobre el nivel del mar. El volcán se formó hace unos 11.000 años tras una erupción masiva y se caracteriza por su forma redondeada sin cráter. En la cima se encuentran las ruinas de un templo galorromano de Mercurio del siglo II, lo que subraya la importancia histórica de este lugar. Hoy en día, el Puy de Dôme es un importante destino turístico y forma parte del Patrimonio Natural de la Humanidad de la UNESCO desde 2018 como parte del sitio tectónico de la Chaîne des Puys y la falla de Limagne. Los visitantes pueden llegar a la cima a pie por el antiguo sendero de peregrinación \"Sentier des Muletiers\" o con el tren de cremallera \"Panoramique des Dômes\". La montaña ofrece una vista panorámica espectacular de los 80 conos volcánicos circundantes y es también un lugar popular para el parapente.",
      pt: "O Puy de Dôme é um domo de lava proeminente e o vulcão mais famoso da Chaîne des Puys, no Maciço Central francês. Localiza-se a cerca de 15 quilómetros da cidade de Clermont-Ferrand e atinge uma altitude de 1465 metros acima do nível do mar. O vulcão formou-se há cerca de 11.000 anos através de uma erupção massiva e caracteriza-se pela sua forma arredondada sem cratera. No topo encontram-se as ruínas de um templo galo-romano de Mercúrio do século II, o que sublinha a importância histórica deste local. Hoje, o Puy de Dôme é um destino turístico importante e pertence ao Património Mundial da UNESCO desde 2018 como parte do sítio tectónico da Chaîne des Puys e da falha de Limagne. Os visitantes podem chegar ao cume a pé pelo antigo trilho de peregrinação \"Sentier des Muletiers\" ou com o comboio de cremalheira \"Panoramique des Dômes\". A montanha oferece uma vista panorâmica espetacular sobre os 80 cones vulcânicos circundantes e é também um local popular para a prática de parapente.",
      fr: "Le Puy de Dôme est un dôme de lave marquant et le volcan le plus célèbre de la Chaîne des Puys dans le Massif central français. Il est situé à environ 15 kilomètres de la ville de Clermont-Ferrand et culmine à 1465 mètres d'altitude. Le volcan s'est formé il y a environ 11 000 ans à la suite d'une éruption massive et se distingue par sa forme arrondie sans cratère. Au sommet se trouvent les ruines d'un temple de Mercure gallo-romain du IIe siècle, ce qui souligne l'importance historique de ce lieu. Aujourd'hui, le Puy de Dôme est une destination touristique majeure et est inscrit au patrimoine mondial de l'UNESCO depuis 2018 au titre de la Chaîne des Puys - faille de Limagne. Les visiteurs peuvent atteindre le sommet soit à pied par l'ancien chemin de pèlerinage \"Sentier des Muletiers\", soit par le train à crémaillère \"Panoramique des Dômes\". La montagne offre une vue panoramique spectaculaire sur les 80 cônes volcaniques environnants et est également un site de décollage prisé pour les parapentistes.",
    },
