      ro: ["Altitudinea medie variază între 600 și 900 de metri.", "Inclus în patrimoniul mondial UNESCO din anul 2011.", "Cunoscut pentru protestele fermierilor din perioada 1971-1981.", "Găzduiește satul fortificat templier La Couvertoirade.", "Zonă principală de pășunat pentru oile ce produc laptele de Roquefort.", "Compus din calcar jurasic cu numeroase sisteme de peșteri."],
      en: ["The plateau's average elevation is between 600 and 900 meters.", "Designated as a UNESCO World Heritage site in 2011.", "Famous for the 'Larzac struggle' (1971–1981) against military expansion.", "Home to La Couvertoirade, a perfectly preserved Templar village.", "It is the primary grazing land for sheep used in Roquefort production.", "Composed of Jurassic limestone with extensive subterranean networks."],
      es: ["Altitud media entre 600 y 900 metros.", "Parte del Patrimonio de la Humanidad de la UNESCO desde el año 2011.", "Conocido por la 'Lucha del Larzac' (1971-1981) contra el ejército.", "Hogar de la ciudad templaria fortificada de La Couvertoirade.", "Principal área de pasto para ovejas para la producción de Roquefort.", "Compuesto por caliza jurásica con numerosos sistemas de cuevas subterráneas."],
      pt: ["Altitude média entre 600 e 900 metros.", "Parte do Património Mundial da UNESCO desde o ano 2011.", "Conhecido pela 'Luta do Larzac' (1971-1981) contra o exército.", "Lar da cidade templária fortificada de La Couvertoirade.", "Principal área de pastagem para ovelhas para a produção de Roquefort.", "Composto por calcário jurássico com numerosos sistemas de grutas subterrâneas."],
