      hu: ["A hegycsúcs magassága 848 méter.", "Egy 70 méter magas távközlési adótorony található a tetején.", "A hegy jelzi a Grands Causses déli végét.", "Tiszta időben ellátni innen a 200 km-re lévő Pireneusokig.", "Főként jura kori mészkőből épül fel.", "A felszálló légáramlatok miatt a siklóernyősök kedvelt helye."],
