      en: ["The peak reaches an altitude of 848 meters.", "It hosts a 70-meter-tall telecommunications mast.", "It marks the southern terminus of the Grands Causses region.", "Provides views of the Pyrenees, over 200 km away, in clear weather.", "The mountain is primarily composed of Jurassic limestone.", "A popular spot for paragliding due to strong thermal updrafts."],
