      hu: ["Legmagasabb pontja 1753 méterrel van a tengerszint felett.", "Két csúcsból áll: az északi és a déli csúcsból.", "Vízválasztó az Atlanti-óceán és a Földközi-tenger között.", "Geológiailag vulkanikus fonolit kőzet építi fel.", "A közelben fekvő Les Estables a régió legmagasabban fekvő települése.", "Híres a 'Fin Gras du Mézenc' nevű, oltalom alatt álló marhahúsról."],
      ro: ["Vârful atinge o altitudine de 1753 de metri.", "Este format din două culmi: vârful nordic și cel sudic.", "Servește drept cumpănă a apelor între Atlantic și Mediterana.", "Compus geologic din roci vulcanice de tip fonolit.", "Cea mai înaltă localitate locuită din zonă este Les Estables.", "Renumit pentru carnea de vită protejată 'Fin Gras du Mézenc'."],
      en: ["The peak reaches an elevation of 1,753 meters.", "It consists of two distinct summits: North and South.", "Acts as the continental divide between the Atlantic and Mediterranean.", "The mountain is geologically composed of volcanic phonolite.", "Nearby Les Estables is the highest village in the Massif Central.", "Famous for its premium 'Fin Gras du Mézenc' AOC beef."],
      es: ["El punto más alto se encuentra a 1753 metros sobre el nivel del mar.", "Consta de dos picos: el pico norte y el pico sur.", "Sirve como divisoria de aguas entre el Atlántico y el Mediterráneo.", "Geológicamente compuesto de roca volcánica fonolita.", "El lugar habitado más alto de la región es el cercano Les Estables.", "Conocido por la carne de vacuno protegida 'Fin Gras du Mézenc'."],
      pt: ["O ponto mais alto situa-se a 1753 metros acima do nível do mar.", "Consiste em dois cumes: o cume norte e o cume sul.", "Serve como divisor de águas entre o Atlântico e o Mediterrâneo.", "Geologicamente constituído por rocha vulcânica de fonolito.", "O local habitado mais alto da região é a vizinha Les Estables.", "Conhecido pela carne de bovino protegida 'Fin Gras du Mézenc'."],
      fr: ["Le point culminant s'élève à 1753 mètres au-dessus du niveau de la mer.", "Il est composé de deux sommets : le sommet nord et le sommet sud.", "Il sert de ligne de partage des eaux entre l'Atlantique et la Méditerranée.", "Géologiquement formé de roches volcaniques phonolitiques.", "Le village le plus haut de la région est Les Estables, tout proche.", "Réputé pour sa viande bovine AOP 'Fin Gras du Mézenc'."],
