      ro: ["Bogată în apă", "Limousin", "Parc Natural Regional", "Zonă împădurită"],
      en: ["Water-rich", "Limousin", "Regional Nature Park", "Forest area"],
      es: ["Rico en agua", "Limosín", "Parque Natural Regional", "Zona boscosa"],
