      es: "Una cadena montañosa en la región del Drôme. El entorno está caracterizado por paisajes de colinas y la confluencia de ríos locales.",
      pt: "Uma cordilheira na região de Drôme. O ambiente é caracterizado por paisagens de colinas e pela confluência de rios locais.",
      fr: "Une chaîne de montagnes dans la Drôme. Les environs sont marqués par des paysages vallonnés et la confluence de rivières locales.",
