    imageHint: "Mont Lure forested ridge",
    descriptionAdvanced: {
      de: "Die Montagne de Lure ist ein markantes Gebirgsmassiv in der Provence, das sich über 42 Kilometer im Departement Alpes-de-Haute-Provence erstreckt. Geologisch wird sie oft als die 'kleine Schwester' des Mont Ventoux bezeichnet, da sie ähnliche Kalksteinformationen und eine charakteristische Ost-West-Ausrichtung aufweist. Die höchste Erhebung ist der Signal de Lure mit 1826 Metern, der einen spektakulären Blick von den Alpen bis zum Mittelmeer bietet. Das Relief ist auf der Südseite sanft abfallend und sonnig, während die Nordseite steil und schattig ist, was zu einer großen Vielfalt an Mikroklimata führt. In der Geschichte war der Berg für seine Kräutersammler bekannt, die hier wertvolle Heilpflanzen für die Apotheken der Region fanden. Heute beherbergt der Berg ein bedeutendes astronomisches Observatorium, da die Luftqualität und die geringe Lichtverschmutzung hier ideal sind. Das Gebiet ist im Sommer ein beliebtes Wanderrevier und bietet im Winter Möglichkeiten für den nordischen Skisport.",
      hu: "A Montagne de Lure egy jellegzetes hegység Provence-ban, amely 42 kilométer hosszan nyúlik el Alpes-de-Haute-Provence megyében. Geológiailag gyakran a Mont Ventoux 'kistestvéreként' emlegetik, mivel hasonló mészkőformációkkal és jellegzetes kelet-nyugati tájolással rendelkezik. Legmagasabb pontja a 1826 méteres Signal de Lure, amely látványos kilátást nyújt az Alpoktól egészen a Földközi-tengerig. A domborzat a déli oldalon enyhén lejtős és napos, míg az északi oldalon meredek és árnyékos, ami a mikroklímák nagy változatosságát eredményezi. A történelem során a hegy gyógynövénygyűjtőiről volt ismert, akik értékes gyógyhatású növényeket találtak itt a régió gyógyszertárai számára. Ma a hegy egy jelentős csillagászati obszervatóriumnak ad otthont, mivel a levegő minősége és az alacsony fényszennyezés itt ideális. A terület nyáron kedvelt túrázóhely, télen pedig lehetőséget nyújt az északi síelésre.",
      ro: "Montagne de Lure este un masiv muntos proeminent în Provence, care se întinde pe 42 de kilometri în departamentul Alpes-de-Haute-Provence. Din punct de vedere geologic, este adesea numit 'sora mai mică' a muntelui Mont Ventoux, având formațiuni calcaroase similare și o orientare caracteristică est-vest. Cea mai înaltă cotă este Signal de Lure, la 1826 de metri, oferind o vedere spectaculoasă de la Alpi până la Marea Mediterană. Relieful este ușor înclinat și însorit pe partea sudică, în timp ce partea nordică este abruptă și umbrită, ceea ce duce la o mare varietate de microclimate. În istorie, muntele a fost cunoscut pentru culegătorii de plante medicinale, care găseau aici specii valoroase pentru farmaciile din regiune. Astăzi, muntele găzduiește un observator astronomic important, deoarece calitatea aerului și poluarea luminoasă scăzută sunt ideale aici. Zona este o destinație populară de drumeție vara și oferă posibilități pentru schi nordic iarna.",
      en: "The Montagne de Lure is a prominent mountain massif in Provence, stretching for 42 kilometers across the Alpes-de-Haute-Provence department. Geologically, it is often referred to as the 'little sister' of Mont Ventoux, as it shares similar limestone formations and a characteristic east-west orientation. The highest point is the Signal de Lure at 1,826 meters, providing a spectacular panoramic view from the Alps to the Mediterranean Sea. The southern slopes of the relief are gently inclined and sunny, while the northern face is steep and shaded, resulting in a wide range of microclimates. Historically, the mountain was famous for its herbalists who collected valuable medicinal plants for pharmacies throughout the region. Today, it hosts a significant astronomical observatory, benefiting from exceptional air quality and minimal light pollution. The area is a popular destination for hikers in the summer and offers opportunities for Nordic skiing during the winter months.",
      es: "La Montaña de Lure es un macizo montañoso prominente en la Provenza, que se extiende a lo largo de 42 kilómetros en el departamento de Alpes de Alta Provenza. Geológicamente, a menudo se la denomina la 'hermana pequeña' del Mont Ventoux, ya que presenta formaciones de caliza similares y una característica orientación este-oeste. La mayor elevación es el Signal de Lure con 1826 metros, que ofrece una vista espectacular desde los Alpes hasta el Mediterráneo. El relieve es de suave pendiente y soleado en el lado sur, mientras que el lado norte es escarpado y sombrío, lo que conduce a una gran diversidad de microclimas. En la historia, la montaña era conocida por sus recolectores de hierbas, que encontraban aquí valiosas plantas medicinales para las boticas de la región. Hoy en día, la montaña alberga un importante observatorio astronómico, ya que la calidad del aire y la baja contaminación lumínica son ideales aquí. La zona es un destino popular para el senderismo en verano y ofrece posibilidades para el esquí nórdico en invierno.",
      pt: "A Montagne de Lure é um maciço montanhoso marcante na Provença, que se estende por 42 quilómetros no departamento dos Alpes da Alta Provença. Geologicamente, é frequentemente chamada de 'irmã mais nova' do Mont Ventoux, pois apresenta formações calcárias semelhantes e uma orientação este-oeste característica. A elevação mais alta é o Signal de Lure, com 1826 metros, que oferece uma vista espetacular desde os Alpes até ao Mediterrâneo. O relevo é suavemente inclinado e ensolarado no lado sul, enquanto o lado norte é íngreme e sombrio, o que leva a uma grande diversidade de microclimas. Historicamente, a montanha era conhecida pelos seus colhedores de ervas, que aqui encontravam plantas medicinais valiosas para as farmácias da região. Atualmente, a montanha abriga um importante observatório astronómico, uma vez que a qualidade do ar e a baixa poluição luminosa são ideais aqui. A área é um destino popular para caminhadas no verão e oferece oportunidades para o esqui nórdico no inverno.",
      fr: "La montagne de Lure est un massif imposant de Provence, s'étirant sur 42 kilomètres dans le département des Alpes-de-Haute-Provence. Géologiquement, elle est souvent qualifiée de 'petite sœur' du Mont Ventoux car elle présente des formations calcaires similaires et une orientation est-ouest identique. Son point culminant est le signal de Lure à 1826 mètres, offrant un panorama grandiose des Alpes jusqu'à la Méditerranée. Le relief descend en pente douce au sud tandis que le versant nord est abrupt et ombragé, créant une riche variété de microclimat. Historiquement, le massif était réputé pour ses herboristes qui y cueillaient des plantes médicinales pour les apothicaires de la région. Aujourd'hui, la montagne accueille un observatoire astronomique majeur, la pureté de l'air et la faible pollution lumineuse y étant idéales. Le site est un lieu de randonnée estival prisé et permet la pratique du ski nordique en hiver.",
    },
