      hu: ["Legmagasabb pontja az 1826 méteres Signal de Lure", "A hegység 42 kilométer hosszan terül el", "Itt található a Saint-Michel-l'Observatoire obszervatórium", "A mészkő domborzatot erős karsztjelenségek jellemzik", "Jean Giono író hazája és ihletője volt", "2010 óta a Luberon-Lure UNESCO Bioszféra-rezervátum része"],
