      en: ["Highest point is the Signal de Lure at 1,826 meters", "The mountain range extends for 42 kilometers", "Home to the Saint-Michel-l'Observatoire astronomical site", "Limestone relief is characterized by karst features", "Was the home and inspiration of writer Jean Giono", "Part of the Luberon-Lure UNESCO Biosphere Reserve since 2010"],
      es: ["El punto más alto es el Signal de Lure con 1826 metros.", "La montaña se extiende a lo largo de 42 kilómetros.", "Alberga el observatorio de Saint-Michel-l'Observatoire.", "El relieve de caliza está fuertemente marcado por fenómenos cársticos.", "Fue el hogar del escritor Jean Giono.", "Reserva de la Biosfera de la UNESCO Luberon-Lure desde 2010."],
      pt: ["O ponto mais alto é o Signal de Lure com 1826 metros.", "A cordilheira estende-se por um comprimento de 42 quilómetros.", "Abriga o observatório de Saint-Michel-l'Observatoire.", "O relevo calcário é fortemente marcado por fenómenos cársticos.", "Foi a casa do escritor Jean Giono.", "Reserva da Biosfera da UNESCO Luberon-Lure desde 2010."],
      fr: ["Le sommet est le signal de Lure s'élevant à 1826 mètres.", "Le massif s'étire sur une longueur de 42 kilomètres.", "Elle accueille l'observatoire de Saint-Michel-l'Observatoire.", "Le relief calcaire est marqué par de nombreux phénomènes karstiques.", "Elle fut la terre d'inspiration de l'écrivain Jean Giono.", "Classée réserve de biosphère UNESCO Luberon-Lure depuis 2010."],
